SD.LESSONS.forEach(function(L){if(L.cat!=='au10')return;L.steps.forEach(function(s,si){(s.cmp||[]).forEach(function(c,i){var g=GT_AU[L.id+'s'+(si+1)+(i+1)];if(g!==undefined)c.g=g})})});
